<html lang="ja">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ブロック崩し</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #0f0f1a;
    color: #eee;
    font-family: "Segoe UI", "Hiragino Sans", "Noto Sans JP", sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    user-select: none;
  }
  h1 {
    font-size: 22px;
    letter-spacing: 4px;
    margin-bottom: 10px;
    color: #7ecbff;
  }
  #wrap { position: relative; }
  canvas {
    background: linear-gradient(#101828, #0a0f1c);
    border: 2px solid #2c3e5d;
    border-radius: 8px;
    box-shadow: 0 0 30px rgba(80, 140, 255, .25);
    display: block;
  }
  #hud {
    display: flex;
    justify-content: space-between;
    width: 800px;
    max-width: 96vw;
    margin: 8px 2px;
    font-size: 15px;
    color: #9fb6d4;
  }
  #hud b { color: #fff; }
  #overlay {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: rgba(6, 10, 20, .78);
    border-radius: 8px;
    text-align: center;
    padding: 20px;
  }
  #overlay.hidden { display: none; }
  #overlay h2 { font-size: 34px; margin-bottom: 12px; color: #ffd76e; }
  #overlay p { margin: 4px 0; color: #b9cbe4; line-height: 1.7; }
  #overlay button {
    margin-top: 18px;
